export function Workspace({
  title = "{{title}}",
  density = "{{density}}",
  accent = "{{accent}}",
  inspector = {{inspector}},
}) {
  const compact = density === "compact";
  return (
    <div style={{ display: "flex", height: 160, fontFamily: "system-ui, sans-serif", fontSize: 12, color: "#241430", border: "1px solid #24143022" }}>
      <nav style={{ flex: "none", width: 40, background: "#241430", color: "#FAF7F2", display: "flex", alignItems: "flex-start", justifyContent: "center", paddingTop: 12 }}>☰</nav>
      <div style={{ flex: 1, display: "flex", flexDirection: "column", minWidth: 0 }}>
        <header style={{ padding: compact ? "5px 10px" : "10px 14px", fontSize: compact ? 11 : 12, borderBottom: `3px solid ${accent}`, background: "#FAF7F2", fontWeight: 700 }}>{title}</header>
        <div style={{ flex: 1, background: "#fff", display: "flex", alignItems: "center", justifyContent: "center", color: "#24143066" }}>Persistent workspace</div>
      </div>
      {inspector && <aside style={{ flex: "none", width: 90, background: "#FAF7F2", borderLeft: `2px solid ${accent}`, display: "flex", alignItems: "flex-start", justifyContent: "center", paddingTop: 12, color: "#24143099" }}>Properties</aside>}
    </div>
  );
}
